example.code:
#include <iostream>
#include <string>

// Component class (has-a)
class Engine {
public:
    explicit Engine(int horsepower) : horsepower_(horsepower) {}
    int getHorsepower() const { return horsepower_; }
private:
    int horsepower_;
};

// Base class
class Vehicle {
public:
    explicit Vehicle(std::string brand) : brand_(std::move(brand)) {}
    const std::string& getBrand() const { return brand_; }
private:
    std::string brand_;
};

// Derived class: Car is-a Vehicle, and Car has-a Engine
class Car : public Vehicle {
public:
    Car(std::string brand, int hp, std::string model)
        : Vehicle(std::move(brand)), engine_(hp), model_(std::move(model)) {}

    void displayInfo() const {
        std::cout << "Brand: " << getBrand()
                  << ", Model: " << model_
                  << ", Horsepower: " << engine_.getHorsepower() << " HP\n";
    }
private:
    Engine engine_;       // has-a relationship
    std::string model_;   // specialized attribute
};

int main() {
    Car myCar("Toyota", 203, "Camry");
    myCar.displayInfo();
    return 0;
}

body.vi:
Cú pháp kế thừa công khai trong C++ được khai báo với dấu hai chấm và từ khóa `public`:
```cpp
class TwoDimensionalShape : public Shape {
    // ...
};
```
Với kế thừa công khai (`public inheritance`):
1. Mọi thành viên `public` của lớp cơ sở vẫn giữ nguyên trạng thái `public` trong lớp dẫn xuất.
2. Các thành viên `private` của lớp cơ sở VẪN ĐƯỢC KẾ THỪA (vẫn tồn tại trong bộ nhớ của đối tượng dẫn xuất), nhưng lớp dẫn xuất KHÔNG THỂ TRUY CẬP TRỰC TIẾP bằng tên. Chúng chỉ có thể được truy cập hoặc biến đổi thông qua các hàm thành viên public (hoặc protected) được kế thừa từ lớp cơ sở.
3. Các hàm bạn (`friend`) của lớp cơ sở không được kế thừa.

body.en:
Public inheritance in C++ is declared using a colon followed by the access specifier `public`:
```cpp
class TwoDimensionalShape : public Shape {
    // ...
};
```
Under public inheritance:
1. Base class `public` members remain `public` in the derived class.
2. Base class `private` members ARE inherited (they physically exist inside every derived object's memory footprint), but they CANNOT be accessed directly by name within the derived class member functions. They can only be manipulated via public or protected member functions inherited from the base class.
3. Friend functions of a base class are not inherited.

example.code:
#include <iostream>
#include <string>

// Root / Indirect base class
class Shape {
public:
    explicit Shape(std::string name) : name_(std::move(name)) {}
    const std::string& getName() const { return name_; }
private:
    std::string name_; // private to Shape; inherited, but accessible only via getName()
};

// Direct base for Circle, derived from Shape
class TwoDimensionalShape : public Shape {
public:
    explicit TwoDimensionalShape(std::string name) : Shape(std::move(name)) {}
    int getDimensions() const { return 2; }
};

// Leaf derived class
class Circle : public TwoDimensionalShape {
public:
    Circle(std::string name, double radius)
        : TwoDimensionalShape(std::move(name)), radius_(radius) {}

    double getRadius() const { return radius_; }

    void printInfo() const {
        std::cout << "Shape: " << getName()
                  << ", Dimensions: " << getDimensions()
                  << ", Radius: " << radius_ << "\n";
    }
private:
    double radius_;
};

int main() {
    Circle c("Circle", 5.0);
    c.printInfo();
    return 0;
}
